def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        safe_bid = DAILY_SALARY * 0.35
        if hp <= 2 or no_water_days >= 1:
            safe_bid = DAILY_SALARY * 0.75
        return float(min(budget, safe_bid))

    highest_prev_bid = 0.0
    avg_prev_bid = 0.0
    count_prev = 0
    rich_aggressive = 0

    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        prev_bid = None
        if prev:
            prev_bid = prev.get('bid')
        if prev_bid is not None:
            if prev_bid > highest_prev_bid:
                highest_prev_bid = prev_bid
            avg_prev_bid += prev_bid
            count_prev += 1
        if opp.get('budget', 0) >= 140 and opp.get('hp', 0) >= 6:
            rich_aggressive += 1

    if count_prev > 0:
        avg_prev_bid = avg_prev_bid / count_prev
    else:
        avg_prev_bid = DAILY_SALARY * 0.8
        highest_prev_bid = DAILY_SALARY * 0.9

    scarcity = 0
    if supply <= WATER_REQ + 2:
        scarcity = 2
    elif supply <= WATER_REQ + 6:
        scarcity = 1

    emergency = (hp <= 2) or (no_water_days >= 1)
    pressured = (hp <= 4)

    if emergency:
        bid = max(DAILY_SALARY * 1.55, highest_prev_bid + 8.0)
    elif scarcity == 2:
        bid = max(DAILY_SALARY * 1.3, highest_prev_bid + 4.0)
    elif scarcity == 1:
        bid = max(DAILY_SALARY * 1.0, avg_prev_bid + 2.5)
    else:
        if pressured:
            bid = max(DAILY_SALARY * 0.9, avg_prev_bid + 1.5)
        else:
            if highest_prev_bid >= 140:
                bid = DAILY_SALARY * 0.62
            elif highest_prev_bid >= 110:
                bid = DAILY_SALARY * 0.72
            else:
                bid = max(DAILY_SALARY * 0.58, avg_prev_bid * 0.72)

    if rich_aggressive >= 2 and not emergency and scarcity == 0 and hp >= 6:
        bid = min(bid, DAILY_SALARY * 0.6)

    if day >= 8:
        if hp <= 5:
            bid = max(bid, highest_prev_bid + 3.0)
        else:
            bid = max(bid, DAILY_SALARY * 0.8)

    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents are alive, bid a minimal amount to save budget
    if not alive_opponents:
        return min(my_status['budget'], 1.0) # Bid 1.0 to ensure water if available

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        # Ensure 'bid' exists and is not None before adding
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # If there are yesterday's bids, react to the highest one
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # Aggressive bidding threshold (e.g., 85% of daily salary)
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            # If my HP is good, I can afford to save money, let opponents overbid
            if my_status['hp'] > 3:
                return min(my_status['budget'], DAILY_SALARY * 0.3)
            # If my HP is low, I must get water, so bid very aggressively
            return min(my_status['budget'], DAILY_SALARY * 0.95)
        else:\n            # If highest bid is moderate, bid slightly above it to win, but not too much
            # Ensure bid is at least a moderate amount (e.g., 50% of daily salary)
            return min(my_status['budget'], max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5))

    # If no previous bids (e.g., first day or opponents didn't bid), bid based on own HP
    if my_status['hp'] <= 2:
        # Critical HP, bid high to survive
        return min(my_status['budget'], DAILY_SALARY * 0.9)

    # Normal HP, bid moderately
    return min(my_status['budget'], DAILY_SALARY * 0.55)

